\label{lem:diff_costs_upper}
For every typed principal-agent problem $\left(\bm{c}, \bm{F}, \bm{r}\right)$ with $n$ actions and $T$ types, there exists a standard principal-agent problem $\left(\bm{c}', \bm{F}', \bm{r}'\right)$ with $(n-1)T+1$ actions (and a single type) such that
\begin{eqnarray*}
\textsc{Opt-Linear} \left(\bm{c}, \bm{F}, \bm{r}\right) &=& \textsc{Opt-Linear} \left(\bm{c}', \bm{F}', \bm{r}'\right)\\
\textsc{Welfare} \left(\bm{c}, \bm{F}, \bm{r}\right) &=& \textsc{Welfare} \left(\bm{c}', \bm{F}', \bm{r}'\right).
\end{eqnarray*}

\begin{eqnarray*}
\textsc{Opt-Linear} \left(\bm{c}, \bm{F}, \bm{r}\right) &=& \textsc{Opt-Linear} \left(\bm{c}', \bm{F}', \bm{r}'\right)\\
\textsc{Welfare} \left(\bm{c}, \bm{F}, \bm{r}\right) &=& \textsc{Welfare} \left(\bm{c}', \bm{F}', \bm{r}'\right).
\end{eqnarray*}

